#!/usr/bin/env node
/**
 * create-feltdb
 *
 * Interactive CLI for creating new FeltDB applications
 */
import path from 'path';
import { fileURLToPath } from 'url';
import readline from 'readline';
import { spawn, spawnSync } from 'child_process';
import { createProject } from './create.js';
import { FELTDB_PACKAGE_VERSION } from './package-versions.js';
import { configureManagedAccount, finalizeManagedProvisioning } from './managed-account.js';
import { localFeltdbExecutable } from './development-handoff.js';
const __dirname = path.dirname(fileURLToPath(import.meta.url));
function parseArgs(args) {
    const options = {
        runtime: 'browser',
        framework: 'react',
        distributed: true,
        agents: true,
        webllm: true,
        capabilities: 'search',
    };
    for (let i = 0; i < args.length; i++) {
        switch (args[i]) {
            case '--browser':
                options.runtime = 'browser';
                break;
            case '--server':
                options.runtime = 'node';
                break;
            case '--self-host':
                options.runtime = 'self-hosted';
                break;
            case '--managed':
                options.runtime = 'managed';
                break;
            case '--runtime':
                options.runtime = args[++i];
                break;
            case '--framework':
                options.framework = args[++i];
                break;
            case '--no-distributed':
                options.distributed = false;
                break;
            case '--no-agents':
                options.agents = false;
                break;
            case '--webllm':
                options.webllm = true;
                break;
            case '--no-webllm':
                options.webllm = false;
                break;
            case '--capabilities':
                options.capabilities = args[++i];
                break;
        }
    }
    return options;
}
function run(command, args, cwd) {
    return new Promise((resolve, reject) => {
        const child = spawn(command, args, { cwd, stdio: 'inherit' });
        child.once('error', reject);
        child.once('exit', code => code === 0
            ? resolve()
            : reject(new Error(`${command} exited with status ${code ?? 'unknown'}`)));
    });
}
async function prompt(message) {
    const interface_ = readline.createInterface({ input: process.stdin, output: process.stdout });
    return new Promise(resolve => interface_.question(message, value => { interface_.close(); resolve(value.trim()); }));
}
async function promptForProjectName(defaultName = 'feltdb-app') {
    while (true) {
        const value = (await prompt(`What should we name your FeltDB app? (${defaultName}): `)) || defaultName;
        if (/^[a-z0-9][a-z0-9-]*$/.test(value))
            return value;
        console.log('Use lowercase letters, numbers, and dashes (for example: customer-portal).');
    }
}
async function promptSecret(message) {
    if (!process.stdin.isTTY || !process.stdout.isTTY)
        return '';
    const input = process.stdin;
    const output = process.stdout;
    const wasRaw = input.isRaw;
    readline.emitKeypressEvents(input);
    input.setRawMode(true);
    input.resume();
    output.write(message);
    return new Promise(resolve => {
        let value = '';
        const finish = () => { input.off('keypress', onKeypress); input.setRawMode(Boolean(wasRaw)); input.pause(); output.write('\n'); resolve(value); };
        const onKeypress = (character, key) => {
            if (key.ctrl && key.name === 'c')
                process.exit(130);
            if (key.name === 'return' || key.name === 'enter')
                return finish();
            if (key.name === 'backspace') {
                value = value.slice(0, -1);
                return;
            }
            if (!key.ctrl && !key.meta && character)
                value += character;
        };
        input.on('keypress', onKeypress);
    });
}
async function select(message, choices, initialValue) {
    let selected = Math.max(0, choices.findIndex(choice => choice.value === initialValue));
    const input = process.stdin;
    const output = process.stdout;
    const wasRaw = input.isRaw;
    readline.emitKeypressEvents(input);
    input.setRawMode(true);
    input.resume();
    const render = (moveUp) => {
        if (moveUp)
            output.write(`\x1b[${choices.length}A`);
        for (let index = 0; index < choices.length; index++) {
            const choice = choices[index];
            const active = index === selected;
            const detail = choice.description ? ` \x1b[2m— ${choice.description}\x1b[22m` : '';
            output.write(`\x1b[2K\r  ${active ? '\x1b[36m❯' : ' '} ${choice.label}${active ? '\x1b[0m' : ''}${detail}\n`);
        }
    };
    output.write(`${message}\n`);
    render(false);
    return new Promise(resolve => {
        const finish = () => {
            input.off('keypress', onKeypress);
            input.setRawMode(Boolean(wasRaw));
            input.pause();
            resolve(choices[selected].value);
        };
        const onKeypress = (_value, key) => {
            if (key.ctrl && key.name === 'c') {
                output.write('\n');
                input.setRawMode(Boolean(wasRaw));
                process.exit(130);
            }
            if (key.name === 'up')
                selected = (selected - 1 + choices.length) % choices.length;
            else if (key.name === 'down')
                selected = (selected + 1) % choices.length;
            else if (key.name === 'return' || key.name === 'enter')
                return finish();
            else
                return;
            render(true);
        };
        input.on('keypress', onKeypress);
    });
}
async function promptForOptions(defaults) {
    if (!process.stdin.isTTY || !process.stdout.isTTY)
        return defaults;
    console.log('Configure your application. Use ↑/↓ to move and Enter to select.\n');
    const yesNo = [
        { label: 'Yes', value: true },
        { label: 'No', value: false },
    ];
    return {
        runtime: await select('Where should FeltDB run?', [
            { label: 'Browser', value: 'browser', description: 'local-first with durable browser storage' },
            { label: 'Node.js', value: 'node', description: 'application server or worker' },
            { label: 'Self-hosted', value: 'self-hosted', description: 'dedicated FeltDB server' },
            { label: 'Managed', value: 'managed', description: 'FeltDB-hosted persistence, sync, and workloads' },
        ], defaults.runtime),
        framework: await select('Choose an application framework:', [
            { label: 'React', value: 'react' },
            { label: 'Vanilla TypeScript', value: 'vanilla' },
        ], defaults.framework),
        distributed: await select('Enable distributed operation?', yesNo, defaults.distributed),
        agents: await select('Include an autonomous agent example?', yesNo, defaults.agents),
        webllm: await select('Install WebLLM for private natural-language app building?', [
            { label: 'Yes', value: true, description: 'build FeltDB schemas, capabilities, workflows, and UI locally with AI' },
            { label: 'No', value: false, description: 'skip the browser model and AI builder' },
        ], defaults.webllm),
        capabilities: await select('Choose starter capabilities:', [
            { label: 'Search', value: 'search' },
            { label: 'Vector search', value: 'vector' },
            { label: 'Search + vector search', value: 'search,vector' },
        ], defaults.capabilities),
    };
}
async function main() {
    const args = process.argv.slice(2);
    if (args.includes('--help') || args.includes('-h')) {
        console.log(`create-feltdb ${FELTDB_PACKAGE_VERSION}

Create a new FeltDB application with one command.

Usage:
  create-feltdb [project-name] [options]

Examples:
  create-feltdb my-app
  create-feltdb my-app --browser
  create-feltdb my-app --server
  create-feltdb my-app --self-host
  create-feltdb my-app --managed
  create-feltdb my-app --framework react --yes

Deployment Target (Explicit):
  --browser               Local-first with durable browser storage (IndexedDB)
                          Best for: Client-side apps, offline-first experiences
                          No server required, full offline capability

  --server                Node.js server runtime with server-side FeltDB authority
                          Best for: Server-side applications, API servers
                          Requires production FeltDB instance or self-host

  --self-host             Dedicated FeltDB server with Docker Compose
                          Best for: Staging first, then explicit production promotion
                          Generates Docker Compose with persistent /data volume

  --managed               Managed FeltDB runtime
                          Best for: Production without operating servers
                          Requires VITE_FELTDB_URL and VITE_FELTDB_API_KEY

Options:
  --browser                Explicit: Browser runtime with IndexedDB
  --server                 Explicit: Node.js server runtime
  --self-host              Explicit: Self-hosted with Docker Compose
  --managed                Explicit: Managed FeltDB service
  --runtime <runtime>      Alternative: Set runtime (browser, node, self-hosted, managed)
  --framework <framework>  Choose framework: react or vanilla (default: react)
  --no-distributed         Disable distributed operation
  --no-agents              Exclude agent examples
  --webllm                 Include the private natural-language FeltDB app builder (default)
  --no-webllm              Do not install WebLLM or generate the AI builder
  --capabilities <list>    Choose capabilities: search, vector, or search,vector
  --no-install             Skip npm install
  --no-start               Skip automatic feltdb dev startup
  -y, --yes                Use all defaults (non-interactive mode)
  -h, --help               Show this help message
  --version                Show version number

Environment Variables:
  FELTDB_IMAGE             Override the default self-hosted container image
  NODE_ENV                 Set to 'development' or 'production'

Learn more: https://github.com/rkendel1/feltdb`);
        return;
    }
    if (args.includes('--version')) {
        console.log(FELTDB_PACKAGE_VERSION);
        return;
    }
    // Find project name (first non-flag argument)
    let projectName = 'feltdb-app';
    let projectNameProvided = false;
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (!arg.startsWith('-')) {
            projectName = arg;
            projectNameProvided = true;
            break;
        }
        // Skip next arg if current arg is a flag that takes a value
        if (arg === '--runtime' || arg === '--framework' || arg === '--capabilities') {
            i++;
        }
    }
    const shouldAutoYes = args.includes('--yes') || args.includes('-y');
    const shouldInstall = !args.includes('--no-install');
    const shouldStart = !args.includes('--no-start');
    let options = parseArgs(args);
    if (!projectNameProvided && !shouldAutoYes && process.stdin.isTTY && process.stdout.isTTY) {
        projectName = await promptForProjectName(projectName);
    }
    if (!/^[a-z0-9][a-z0-9-]*$/.test(projectName)) {
        throw new Error('Application names must use lowercase letters, numbers, and dashes.');
    }
    const runtimeDescriptions = {
        'browser': 'Browser with IndexedDB (local-first, no server)',
        'node': 'Node.js server (server-side authority)',
        'self-hosted': 'Self-hosted with Docker Compose (staging)',
        'managed': 'Managed FeltDB service (hosted persistence, sync, and workloads)',
    };
    if (!runtimeDescriptions[options.runtime]) {
        throw new Error(`Unsupported runtime "${options.runtime}". Choose browser, node, self-hosted, or managed.`);
    }
    console.log('\n✨ Creating FeltDB Application\n');
    if (!shouldAutoYes) {
        options = await promptForOptions(options);
    }
    // Display the deployment target explicitly
    console.log('\n═══════════════════════════════════════════════');
    console.log('📦 DEPLOYMENT TARGET');
    console.log('═══════════════════════════════════════════════');
    console.log(`\nRuntime:       ${options.runtime.toUpperCase()}`);
    console.log(`Description:   ${runtimeDescriptions[options.runtime]}`);
    console.log(`Framework:     ${options.framework}`);
    console.log(`Distributed:   ${options.distributed ? 'yes' : 'no'}`);
    console.log(`Agents:        ${options.agents ? 'yes' : 'no'}`);
    console.log(`WebLLM:        ${options.webllm ? 'yes — natural-language app builder' : 'no'}`);
    console.log(`Capabilities:  ${options.capabilities}`);
    console.log('\n═══════════════════════════════════════════════\n');
    const projectDir = path.resolve(process.cwd(), projectName);
    let projectCreated = false;
    try {
        await createProject({
            projectName,
            autoYes: shouldAutoYes,
            templatesDir: path.join(__dirname, 'template'),
            runtime: options.runtime,
            framework: options.framework,
            distributed: options.distributed,
            agents: options.agents,
            webllm: options.webllm,
            capabilities: options.capabilities,
            showNextSteps: false,
        });
        projectCreated = true;
        if (options.runtime === 'managed') {
            console.log('\n☁️  Setting up your managed FeltDB account...\n');
            const email = process.env.FELTDB_MANAGED_EMAIL || (shouldAutoYes ? '' : await prompt('Email: '));
            const password = process.env.FELTDB_MANAGED_PASSWORD || (shouldAutoYes ? '' : await promptSecret('Password (8+ characters): '));
            if (!email || password.length < 8) {
                throw new Error('Managed setup needs an email and an 8+ character password. In non-interactive mode set FELTDB_MANAGED_EMAIL and FELTDB_MANAGED_PASSWORD.');
            }
            const managed = await configureManagedAccount({ projectDir, applicationName: projectName, namespace: projectName, email, password });
            console.log(`✓ Managed application: ${managed.application.name}`);
            console.log(`✓ Managed environment written to ${projectName}/.env.local`);
        }
        console.log('\n✅ FeltDB application created successfully!\n');
        const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
        if (options.runtime === 'managed' && !shouldInstall) {
            throw new Error('Managed provisioning requires dependency installation so the initial revision can be built, published, promoted, and verified. Remove --no-install.');
        }
        if (shouldInstall) {
            console.log(`📦 Installing application, Studio${options.webllm ? ', and local WebLLM app builder' : ''} dependencies...\n`);
            await run(npm, ['install'], projectDir);
            if (options.runtime === 'managed') {
                console.log('\n☁️  Publishing and verifying the initial managed revision...\n');
                await run(localFeltdbExecutable(projectDir), ['publish', '--yes', '--approve-destructive-changes'], projectDir);
                const finalized = await finalizeManagedProvisioning({ projectDir });
                console.log(`✓ Managed runtime verified at revision ${finalized.revisionId}`);
            }
        }
        if (shouldStart) {
            if (!shouldInstall) {
                console.log(`Start after installing dependencies:\n  cd ${projectName}\n  npm install\n  npm run feltdb:dev\n`);
            }
            else {
                if (options.runtime === 'self-hosted' && spawnSync('docker', ['version'], { stdio: 'ignore' }).status !== 0) {
                    console.log('\n✅ Project and Docker image definition are ready.');
                    console.log('Docker is not currently running, so startup was skipped.');
                    console.log(`Start Docker Desktop, then run:\n  cd ${projectName}\n  npm run feltdb:dev`);
                    console.log('Build the production application image with: docker compose build app');
                }
                else {
                    console.log('\n🚀 Starting your FeltDB development session...\n');
                    await run(localFeltdbExecutable(projectDir), ['dev'], projectDir);
                }
            }
        }
        else {
            console.log('Project is ready. Start the application with:');
            console.log(`  cd ${projectName}`);
            if (!shouldInstall)
                console.log('  npm install');
            console.log('  npm run dev');
            console.log('Start FeltDB development tooling separately with:');
            console.log('  npm run feltdb:dev');
        }
    }
    catch (error) {
        console.error(projectCreated
            ? `❌ The project was created at ${projectDir}, but setup or startup failed:`
            : '❌ Failed to create project:', error);
        process.exit(1);
    }
}
main();
